import {analyze,dimensions,priority,band,sorted,markdown} from './engine.mjs';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let files=[],report=null;const MAX=1_000_000;
const sample=`Objective: Automate customer support triage and route tickets to the right team.
Inputs: Customer emails and historical support tickets, including customer data.
Output: An automated routing decision and a summary for each ticket.
Target: 20,000 users at launch. The model calls an external vendor API for each ticket.
Workflow: Ingest ticket -> classify -> write assignment -> notify the support team.
Launch date: 2026-12-01
Budget: USD 5,000/month
Project owner: TBD
Support owner: TBD
Decision log from delivery review:
Launch date: 2026-12-15
Budget: USD 8,000/month
The service will deploy to production after the pilot. Each accepted decision is written immediately.
The data team will provide a CSV export before launch. Model performance will be reviewed informally by the product team.
The launch is intended to reduce manual triage time and make routing more consistent across shifts. No pilot results are attached to this brief.`;
$('methodGrid').innerHTML=dimensions.map(d=>`<div class="method-item"><strong>${esc(d[0])}</strong> · ${esc(d[3])}</div>`).join('');
function error(message){$('error').textContent=message;$('error').hidden=!message;}
function dirty(){$('charCount').textContent=`${$('materials').value.length.toLocaleString()} characters`;if(report)$('stale').hidden=false;}
$('materials').addEventListener('input',dirty);$('projectName').addEventListener('input',dirty);
$('sample').onclick=()=>{if(($('materials').value.trim()||files.length)&&!confirm('Replace the current materials with the example project?'))return;$('materials').value=sample;$('projectName').value='Support automation · Example';files=[];renderFiles();dirty();error('');};
function renderFiles(){$('fileList').innerHTML=files.map((f,i)=>`<div class="file"><span>${esc(f.name)} · ${new TextEncoder().encode(f.text).length.toLocaleString()} bytes</span><button data-remove="${i}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('');}
$('fileList').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){files.splice(Number(b.dataset.remove),1);renderFiles();dirty();}};
let importing=false;
async function addFiles(incoming){if(importing){error('Wait for the current import to finish.');return;}importing=true;$('run').disabled=true;try{error('');const next=[...files];let bytes=next.reduce((n,f)=>n+new TextEncoder().encode(f.text).length,0)+new TextEncoder().encode($('materials').value).length;for(const f of incoming){if(!/\.(txt|md|csv|json)$/i.test(f.name))throw Error(`${f.name}: unsupported format. Export PDF or Word documents to plain text first.`);bytes+=f.size;if(bytes>MAX)throw Error('Combined materials exceed 1 MB. Remove a file or use a smaller extract.');const data=await f.arrayBuffer();const text=new TextDecoder('utf-8',{fatal:true}).decode(data);if(text.includes('\0'))throw Error(`${f.name}: binary content is not supported.`);if(!text.trim())throw Error(`${f.name} is empty.`);if(next.some(d=>d.name===f.name))throw Error(`Duplicate filename: ${f.name}. Rename it to keep evidence references unique.`);next.push({name:f.name,text});}files=next;renderFiles();dirty();}catch(e){error(e.message);}finally{$('files').value='';importing=false;$('run').disabled=false;}}
$('files').onchange=e=>addFiles(e.target.files);$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('drag');};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');addFiles(e.dataTransfer.files);};
$('run').onclick=async()=>{error('');const docs=[...files];if($('materials').value.trim())docs.unshift({name:'Pasted project brief',text:$('materials').value});if(docs.reduce((n,d)=>n+new TextEncoder().encode(d.text).length,0)>MAX){error('Combined materials exceed 1 MB.');return;}$('run').disabled=true;$('run').textContent='Reviewing materials…';await new Promise(resolve=>setTimeout(resolve,30));try{report=analyze(docs);report.title=$('projectName').value.trim()||'Untitled project';$('search').value='';$('typeFilter').value='all';$('statusFilter').value='all';$('results').hidden=false;$('stale').hidden=true;$('thin').hidden=!report.thin;$('reportTitle').textContent=report.title;$('reportMeta').textContent=`${report.documents.length} source(s) reviewed · ${report.engine} · ${new Date(report.createdAt).toLocaleString()}`;renderReport();$('results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){error(e.message);}finally{$('run').disabled=false;$('run').innerHTML='Run project audit <span>↗</span>';}};
function renderReport(){renderStats();renderFindings();$('coverage').innerHTML=report.coverage.map(c=>`<div class="coverage-row">${esc(c.name)}<span class="${c.state==='Review needed'?'warn':''}">${esc(c.state)}</span></div>`).join('');$('model').innerHTML=report.model.map(x=>`<li>${esc(x)}</li>`).join('');$('profiles').innerHTML=report.profiles.map(p=>`<div class="panel profile"><strong>${esc(p.source)}</strong><br>${p.error?esc(p.error):`${p.rows} data rows · ${p.columns} columns<br>${p.missing} empty/absent cells · ${p.malformed} ragged records`}</div>`).join('');}
function renderStats(){const f=report.findings;$('stats').innerHTML=[[f.length,'REVIEW CANDIDATES'],[f.filter(x=>['HIGH','CRITICAL'].includes(band(priority(x.axes)))).length,'HIGH / CRITICAL'],[f.filter(x=>priority(x.axes)===null).length,'AWAITING SCORING'],[f.filter(x=>x.status==='Verified').length,'VERIFIED BY YOU']].map(([n,label])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('');}
function scoreLine(f){const n=priority(f.axes);return n===null?'Impact is unscored. Confirm all five axes below.':`(${f.axes.S} × ${f.axes.P} × ${f.axes.D} × ${f.axes.T}) / ${f.axes.E} = ${n} · Reviewer-supplied priority`;}
function renderFindings(){if(!report)return;const q=$('search').value.toLowerCase(),type=$('typeFilter').value,status=$('statusFilter').value;const fs=sorted(report.findings).filter(f=>(type==='all'||f.type===type)&&(status==='all'||f.status===status)&&JSON.stringify(f).toLowerCase().includes(q));$('findings').innerHTML=fs.map(f=>{const n=priority(f.axes);return `<article class="finding" data-id="${f.id}"><div class="finding-top"><span class="tag">${f.id} / TYPE ${f.type} · ${esc(f.dimension)}</span><span class="badge ${band(n)}">${n===null?'UNSCORED':n+' / '+band(n)}</span></div><h3>${esc(f.title)}</h3><div class="confidence">${f.confidence} CONFIDENCE · ${esc(f.basis)}</div><p>${esc(f.missing)}</p>${f.evidence.map((e,i)=>`<div class="evidence"><blockquote>${esc(e.quote)}</blockquote><button data-source="${i}">${esc(e.source)} · line ${e.line} ↗</button></div>`).join('')}<p>${esc(f.impact)}</p><span class="detail-label">NEXT ACTION / ${esc(f.owner)}</span><p>${esc(f.recommendation)}</p><details><summary>Verification plan & priority scoring</summary><span class="detail-label">VERIFY IT</span><p>${esc(f.verify)}</p><span class="detail-label">RATE EACH AXIS · 1–5</span><p>Severity: 1 cosmetic → 5 project-killing. Probability: 1 speculation → 5 direct evidence. Detectability failure: 1 immediate → 5 silent. Time: 1 distant → 5 within a month. Effort to verify: 1 today → 5 a quarter.</p><div class="rating-grid">${[['S','Severity'],['P','Probability'],['D','Silent failure'],['T','Time to hit'],['E','Verify effort']].map(([key,label])=>`<label>${label}<select data-axis="${key}" aria-label="${label} for ${f.id}"><option value="">?</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${f.axes[key]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><p class="score-line">${esc(scoreLine(f))}</p><p>Ratings are your judgments, not calibrated probabilities. Exported reports include the arithmetic.</p></details><div class="status"><label for="status-${f.id}">Review status</label><select id="status-${f.id}" data-status>${['Open','Verified','Dismissed'].map(v=>`<option ${v===f.status?'selected':''}>${v}</option>`).join('')}</select></div></article>`;}).join('')||'<div class="empty">No findings match this view.<br>No detected gaps is not a completeness guarantee.</div>';}
$('findings').onchange=e=>{const card=e.target.closest('[data-id]');if(!card)return;const f=report.findings.find(x=>x.id===card.dataset.id);if(e.target.dataset.axis){f.axes[e.target.dataset.axis]=e.target.value?Number(e.target.value):null;card.querySelector('.score-line').textContent=scoreLine(f);const n=priority(f.axes),badge=card.querySelector('.badge');badge.className=`badge ${band(n)}`;badge.textContent=n===null?'UNSCORED':`${n} / ${band(n)}`;if(n!==null){const open=Array.from($('findings').querySelectorAll('details[open]')).map(x=>x.closest('[data-id]').dataset.id);renderFindings();for(const id of open){const detail=$('findings').querySelector(`[data-id="${id}"] details`);if(detail)detail.open=true;}}}else if(e.target.hasAttribute('data-status')){f.status=e.target.value;if($('statusFilter').value!=='all')renderFindings();}renderStats();};
$('findings').onclick=e=>{const b=e.target.closest('[data-source]');if(!b)return;const f=report.findings.find(x=>x.id===b.closest('[data-id]').dataset.id),ev=f.evidence[Number(b.dataset.source)],doc=report.documents[ev.docIndex];$('sourceTitle').textContent=`${ev.source} · line ${ev.line}`;$('sourceText').innerHTML=doc.text.split(/\r?\n/).map((line,i)=>`<span class="source-line ${i+1===ev.line?'hit':''}">${i+1}  ${esc(line)}</span>`).join('');$('sourceDialog').showModal();$('sourceText').querySelector('.hit')?.scrollIntoView({block:'center'});};$('closeSource').onclick=()=>$('sourceDialog').close();
for(const id of ['search','typeFilter','statusFilter'])$(id).addEventListener(id==='search'?'input':'change',renderFindings);
function download(content,extension,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=`sentinel-${report.title.replace(/[^a-z0-9]+/gi,'-').slice(0,60)}.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('exportMd').onclick=()=>{if(report)download(`# ${report.title}\n\n${markdown(report)}`,'md','text/markdown');};$('exportJson').onclick=()=>{if(report)download(JSON.stringify({...report,findings:sorted(report.findings).map(f=>({...f,score:priority(f.axes),band:band(priority(f.axes))}))},null,2),'json','application/json');};
function view(method){$('method').hidden=!method;$('audit').hidden=method;$('methodNav').classList.toggle('active',method);$('auditNav').classList.toggle('active',!method);} $('methodNav').onclick=()=>view(true);$('auditNav').onclick=$('back').onclick=()=>view(false);
